/* athar — minimal highlight.js bundle: core engine + the languages the docs
   actually fence or are likely to (bash, go, sql, json, yaml, html/xml,
   javascript, nginx — nginx doubles as the nearest built-in lexer for a
   Caddyfile, which has no dedicated highlight.js grammar) + plaintext as a
   safe fallback so an unrecognised fence never throws.
   Source: highlight.js (see highlight.min.js.LICENSE). Bundled locally with
   esbuild so the site never fetches highlighting from a CDN. */
import hljs from 'highlight.js/lib/core';
import bash from 'highlight.js/lib/languages/bash';
import go from 'highlight.js/lib/languages/go';
import sql from 'highlight.js/lib/languages/sql';
import json from 'highlight.js/lib/languages/json';
import yaml from 'highlight.js/lib/languages/yaml';
import xml from 'highlight.js/lib/languages/xml';
import javascript from 'highlight.js/lib/languages/javascript';
import nginx from 'highlight.js/lib/languages/nginx';
import plaintext from 'highlight.js/lib/languages/plaintext';
import ini from 'highlight.js/lib/languages/ini';

hljs.registerLanguage('bash', bash);
hljs.registerLanguage('sh', bash);
hljs.registerLanguage('shell', bash);
hljs.registerLanguage('go', go);
hljs.registerLanguage('golang', go);
hljs.registerLanguage('sql', sql);
hljs.registerLanguage('json', json);
hljs.registerLanguage('yaml', yaml);
hljs.registerLanguage('yml', yaml);
hljs.registerLanguage('html', xml);
hljs.registerLanguage('xml', xml);
hljs.registerLanguage('javascript', javascript);
hljs.registerLanguage('js', javascript);
hljs.registerLanguage('nginx', nginx);
hljs.registerLanguage('caddyfile', nginx);
hljs.registerLanguage('caddy', nginx);
hljs.registerLanguage('ini', ini);
hljs.registerLanguage('toml', ini);
hljs.registerLanguage('plaintext', plaintext);
hljs.registerLanguage('text', plaintext);

hljs.configure({ languages: ['bash','go','sql','json','yaml','html','javascript','nginx','ini','plaintext'] });

window.hljs = hljs;
